import json

class LogEntry:
    def __init__(self, log_name, resource_type, labels, payload, timestamp=None):
        self.log_name = log_name
        self.resource_type = resource_type
        self.labels = labels
        self.payload = payload
        self.timestamp = timestamp

    def to_json(self):
        return json.dumps({
            "log_name": self.log_name,
            "resource_type": self.resource_type,
            "labels": self.labels,
            "payload": self.payload,
            "timestamp": str(self.timestamp) if self.timestamp else None
        })

class QueryFilter:
    def __init__(self, severity=None, time_range_start=None, time_range_end=None, text_search=None, fields=None):
        self.severity = severity
        self.time_range_start = time_range_start
        self.time_range_end = time_range_end
        self.text_search = text_search
        self.fields = fields or {}

    def to_filter_string(self):
        filters = []
        if self.severity:
            filters.append(f"severity>=\"{self.severity.upper()}\"")
        if self.time_range_start:
            filters.append(f"timestamp>=\"{self.time_range_start.isoformat()}Z\"")
        if self.time_range_end:
            filters.append(f"timestamp<=\"{self.time_range_end.isoformat()}Z\"")
        if self.text_search:
            filters.append(f"textPayload:\"{self.text_search}\" OR jsonPayload:\"{self.text_search}\"")
        for field, value in self.fields.items():
            filters.append(f"jsonPayload.{field}=\"{value}\"")
        return " AND ".join(filters)

from datetime import datetime, timezone
import time

from observability_client import ObservabilityClient
from observability_models import LogEntry
from google.cloud.logging_v2.resource import Resource

def write_correlated_logs(correlation_id, events, config=None):
    config = config or {}
    client = ObservabilityClient(project_id=config["project_id"])
    logging_client = client.get_logging_client()
    logger = logging_client.logger(config["log_name"])

    for event in events:
        payload = {"correlation_id": correlation_id, "event": event}
        timestamp_ms = event.get("timestamp_ms", time.time() * 1000)
        logger.log_struct(
            payload,
            timestamp=datetime.fromtimestamp(timestamp_ms / 1000, tz=timezone.utc),
            resource=Resource(type="global", labels={"project_id": config["project_id"]}),
        )
    return {"submitted": True, "correlation_id": correlation_id}

