    error_logs_response = query_error_logs(time_range_minutes=time_range_minutes, config=config)
    error_logs = error_logs_response["logs"]

    if not error_logs:
        return {"summary": "No error logs found for the specified time range."}

    # In a real scenario, an LLM would summarize these logs.
    # For this example, we'll just concatenate the error messages.
    log_messages = [str(log["payload"]) for log in error_logs]

    # Placeholder for LLM summarization
    summary_text = "\n".join([f"Severity: {log['severity']}, Timestamp: {log['timestamp']}, Payload: {log['payload']}" for log in error_logs])

    return {"summary": f"Incident Summary (last {time_range_minutes} minutes):\n{summary_text}"}

from observability_client import ObservabilityClient

def translate_log_message(log_message_text, target_language_code, config=None):
    config = config or {}
    client = ObservabilityClient(project_id=config["project_id"])
    translate_client = client.get_translate_client()

    translation = translate_client.translate(
        log_message_text, target_language=target_language_code
    )

    return {
        "original_message": log_message_text,
        "translated_message": translation["translatedText"],
        "target_language": target_language_code,
        "detected_source_language": translation["detectedSourceLanguage"],
    }

from observability_client import ObservabilityClient

def embed_log_message(log_message_text, config=None):
    config = config or {}
    client = ObservabilityClient(project_id=config["project_id"])
    embedding_model = client.get_embedding_model()

    embeddings = embedding_model.get_embeddings([log_message_text])

    return {
        "log_message": log_message_text,
        "embedding": embeddings[0].values,
    }
